-- =====================================================================
--  Import des 89 lignes du Google Sheet 2025-2026 (nettoyées)
--  À coller UNE FOIS dans le SQL Editor de Supabase, APRÈS schema.sql.
--
--  Nettoyages appliqués :
--   - dates JJ/MM/AAAA -> ISO ; annee 2025 corrigee en 2026 (coquille, voisins en 2026)
--   - "Cout TTC" : "?" et vides -> NULL ; virgule decimale -> point
--   - prix saisi par erreur dans la colonne "Lien web" -> remis dans le cout
--   - "=>" et espaces multiples nettoyes dans les intitules
--   - statut deduit des colonnes "passee / recue / recuperee"
--   - cout_unitaire laisse vide (source ambigue : parfois total, parfois unitaire)
--
--  Pour repartir de zero : TRUNCATE public.commandes RESTART IDENTITY;
-- =====================================================================

insert into public.commandes
  (created_at, numero, formation, parcours, groupe, encadrant, fournisseur, intitule,
   reference, lien, quantite, cout_unitaire, cout_total, statut, recue_note,
   commandee_at, recue_at, remise_at, commentaire_demandeur)
